def claim(cid,source,locator,context,support,not_established,implication,ids,kind='qualitative',uncertainty='qualitative direction; magnitude and conditional frequency unmeasured'):
 return {'id':cid,'source_id':source,'source_date':sources[source]['date'],'locator':locator,'context':context,'support_kind':kind,'supports':support,'cannot_establish':not_established,'candidate_engine_implication':implication,'input_ids':ids,'uncertainty':uncertainty,'denominator':None if kind!='observed_aggregate' else 'see linked constraint','correlation_group':sources[source]['correlation_group']}

