states=[
 {'id':'clean_retained','definition':'Intended receiver secures the pass within the declared ready-to-act tolerance; no material delivery-caused correction under the declared coding protocol.'},
 {'id':'awkward_retained','definition':'Offense retains live control after reach, bobble, gather, relocation or teammate recovery; record who secures it and consequences rather than implying a clean intended catch.'},
 {'id':'retained_stoppage','definition':'No live clean catch, but offense retains an inbound/other stoppage; disruption can remain without a turnover.'},
 {'id':'live_loss','definition':'Defense obtains control, even if the offense steals it back in a later distinct event.'},
 {'id':'dead_loss','definition':'Offense loses possession by applicable out-of-bounds/violation/event; scorer attribution stored separately.'},
 {'id':'unresolved','definition':'Loose-ball or possession-control decision not yet observed at the horizon; censor/resolve explicitly, never quietly count as a clean catch.'},
]
comparisons=[
 {'id':'PRC01','factor':'delivery placement/timing','hold':'same route, passer/receiver abilities, initial defense, flight/release context','change':'on-target versus low/high/behind/late but reachable, then beyond reachable envelope','direction':'Worse placement can first increase retained corrections, then losses; a reachable ball need not preserve the original shot. No forced monotonic loss from every tiny offset.'},
 {'id':'PRC02','factor':'receiver technique versus physical reach','hold':'identical delivered trajectory and pressure','change':'receiving technique at fixed geometry, then geometry at fixed technique separately','direction':'Better technique should help securing/use where physically feasible; extra reach can expand access without guaranteeing clean control or finish.'},
 {'id':'PRC03','factor':'defensive pressure and flight window','hold':'same intended endpoint, receiver/handler skills and route','change':'interception access or recovery timing, one at a time','direction':'Deflection/loose-ball recovery may preserve offense. Do not count a deflection and resulting loss as two turnovers.'},
 {'id':'PRC04','factor':'downstream cost conditional on retained receipt','hold':'delivered error and current receiver position/release skill','change':'remaining shot clock or defender closure opportunity separately','direction':'Record control time, extra movement, release-ready time, next action and contest at actual release; allow reset/no shot, not just an accuracy multiplier.'},
 {'id':'PRC05','factor':'route context','hold':'declared matched pressure/geometry and separate ability fields','change':'ground roll, aerial lob, perimeter drive outlet/pop strata','direction':'Keep denominators by stratum and terminal type. Different required height, velocity, timing and landing/preparation cannot be collapsed into one universal reception rate.'},
]

